//! Playwright locator actions over the shell CDP bridge.
//!
//! The TS product runs Playwright's injected selector engine. The Rust shell
//! does not ship that engine; this module implements the same operation surface
//! over a documented selector subset:
//!
//! - CSS selectors (default and `css=`),
//! - `id=`, `data-testid=`, `text=` and `role=<role>[name="..."]`,
//! - `xpath=`, `nth=` (including negative) and `>>` chaining,
//! - `internal:` selectors generated by the TS client:
//!   `internal:role=`, `internal:text=`, `internal:label=`, `internal:attr=`,
//!   `internal:testid=`, `internal:and=`, `internal:or=`, `internal:has=`,
//!   `internal:has-not=`, `internal:has-text=`, `internal:has-not-text=` and
//!   `internal:control=enter-frame` (same-origin frames only).
//!
//! Unknown `internal:` selectors and cross-origin frame entry fail explicitly
//! instead of silently mis-resolving. The locator operations (`count`,
//! `allTextContents`, `isVisible`, `isEnabled`, `textContent`, `innerText`,
//! `getAttribute`, `evaluate`, `waitFor`, `click`, `dblclick`, `fill`, `press`,
//! `setChecked`, `selectOption`, `downloadMedia`) dispatch through CDP
//! input/evaluation like the TS manager.

use std::time::{Duration, Instant};

use serde_json::{json, Value};

use crate::browser_control::ShellBrowserPort;
use crate::browser_control_scripts as scripts;

const DEFAULT_TIMEOUT: Duration = Duration::from_secs(3);
const POLL_INTERVAL: Duration = Duration::from_millis(50);

fn timeout_of(action: &Value) -> Duration {
    let millis = action
        .get("timeoutMs")
        .and_then(Value::as_u64)
        .unwrap_or(DEFAULT_TIMEOUT.as_millis() as u64)
        .min(DEFAULT_TIMEOUT.as_millis() as u64);
    Duration::from_millis(millis)
}

fn download_timeout_of(action: &Value) -> Duration {
    let millis = action
        .get("timeoutMs")
        .and_then(Value::as_u64)
        .unwrap_or(DEFAULT_TIMEOUT.as_millis() as u64)
        .min(120_000);
    Duration::from_millis(millis)
}

fn unsupported(message: impl Into<String>) -> (String, String) {
    ("capability_unsupported".to_string(), message.into())
}

fn invalid(message: impl Into<String>) -> (String, String) {
    ("invalid_input".to_string(), message.into())
}

fn timeout_error(message: impl Into<String>) -> (String, String) {
    ("timeout".to_string(), message.into())
}

fn selector_resolver(selector: &str) -> String {
    let encoded = serde_json::to_string(selector).unwrap_or_else(|_| "\"\"".to_string());
    let mut script = String::from("(() => {\n  const selector = ");
    script.push_str(&encoded);
    script.push_str(
        r###";
  function unsupported(message) { throw new Error(message); }
  function normalize(value) { return String(value == null ? "" : value).replace(/\s+/g, " ").trim(); }

  function parseMatcher(raw) {
    const value = String(raw).trim();
    if (value.length > 1 && value[0] === "/" && value.lastIndexOf("/") > 0) {
      const last = value.lastIndexOf("/");
      const regex = new RegExp(value.slice(1, last), value.slice(last + 1));
      return function (text) { return regex.test(String(text == null ? "" : text)); };
    }
    if (value.length > 2 && value[0] === '"' && value.slice(-2) === '"i') {
      const expected = normalize(JSON.parse(value.slice(0, -1))).toLowerCase();
      return function (text) { return normalize(text).toLowerCase().includes(expected); };
    }
    if (value.length > 2 && value[0] === '"' && value.slice(-2) === '"s') {
      const expected = normalize(JSON.parse(value.slice(0, -1)));
      return function (text) { return normalize(text) === expected; };
    }
    if (value.length > 1 && value[0] === '"' && value[value.length - 1] === '"') {
      const expected = normalize(JSON.parse(value));
      return function (text) { return normalize(text) === expected; };
    }
    if (value.length > 1 && value[0] === "'" && value[value.length - 1] === "'") {
      const expected = normalize(value.slice(1, -1));
      return function (text) { return normalize(text) === expected; };
    }
    const expected = value.toLowerCase();
    return function (text) { return normalize(text).toLowerCase().includes(expected); };
  }

  function parseAttributes(raw) {
    const attributes = {};
    const pattern = /\[([^\]=]+?)(?:=((?:"(?:[^"\\]|\\.)*"[is]?|\/(?:[^\/\\]|\\.)*\/[a-z]*|[^\]]+)))?\]/g;
    let match;
    while ((match = pattern.exec(raw))) {
      const name = match[1].trim().toLowerCase();
      attributes[name] = match[2] === undefined
        ? function () { return true; }
        : parseMatcher(match[2].trim());
    }
    return attributes;
  }

  function textOf(element) {
    if (!element) return "";
    return element.innerText || element.textContent || "";
  }

  function matchesText(element, matcher) {
    if (!matcher(textOf(element))) return false;
    for (const child of element.querySelectorAll("*")) {
      if (matcher(textOf(child))) return false;
    }
    return true;
  }

  function roleOf(element) {
    const explicit = element.getAttribute("role");
    if (explicit) return explicit.trim().toLowerCase().split(/\s+/)[0];
    const tag = element.tagName;
    if (tag === "BUTTON") return "button";
    if (tag === "A" && element.hasAttribute("href")) return "link";
    if (tag === "INPUT") {
      const type = (element.getAttribute("type") || "text").toLowerCase();
      if (type === "checkbox") return "checkbox";
      if (type === "radio") return "radio";
      if (type === "range") return "slider";
      if (type === "number") return "spinbutton";
      if (type === "search") return "searchbox";
      if (type === "button" || type === "submit" || type === "reset" || type === "image") return "button";
      return "textbox";
    }
    if (tag === "TEXTAREA") return "textbox";
    if (tag === "SELECT") return element.multiple || element.size > 1 ? "listbox" : "combobox";
    if (/^H[1-6]$/.test(tag)) return "heading";
    if (tag === "IMG") return "img";
    if (tag === "UL" || tag === "OL") return "list";
    if (tag === "LI") return "listitem";
    if (tag === "TABLE") return "table";
    if (tag === "TR") return "row";
    if (tag === "TD") return "cell";
    if (tag === "TH") return "columnheader";
    if (tag === "NAV") return "navigation";
    if (tag === "MAIN") return "main";
    if (tag === "FORM") return "form";
    if (tag === "DIALOG") return "dialog";
    if (tag === "PROGRESS") return "progressbar";
    if (tag === "METER") return "meter";
    if (element.isContentEditable) return "textbox";
    return "";
  }

  function labelsOf(element) {
    const labels = [];
    const aria = element.getAttribute("aria-label");
    if (aria) labels.push(aria);
    const labelledBy = element.getAttribute("aria-labelledby");
    if (labelledBy) {
      const doc = element.ownerDocument || document;
      const text = labelledBy.split(/\s+/).map(function (id) {
        const target = doc.getElementById(id);
        return target ? textOf(target) : "";
      }).join(" ");
      if (normalize(text)) labels.push(text);
    }
    if (element.labels) {
      for (const label of element.labels) labels.push(textOf(label));
    }
    const wrapping = element.closest ? element.closest("label") : null;
    if (wrapping) labels.push(textOf(wrapping));
    const unique = [];
    for (const label of labels) {
      const value = normalize(label);
      if (value && !unique.includes(value)) unique.push(value);
    }
    return unique;
  }

  function accessibleName(element) {
    const labels = labelsOf(element);
    if (labels.length > 0) return labels.join(" ");
    if (element.tagName === "IMG") return element.getAttribute("alt") || "";
    return textOf(element);
  }

  function resolveStep(root, step) {
    if (step.startsWith("internal:")) {
      const body = step.slice("internal:".length);
      if (body.startsWith("role=")) {
        const spec = body.slice("role=".length);
        const bracket = spec.indexOf("[");
        const role = (bracket >= 0 ? spec.slice(0, bracket) : spec).trim().toLowerCase();
        if (!role) unsupported("internal:role requires a role");
        const attributes = bracket >= 0 ? parseAttributes(spec.slice(bracket)) : {};
        const nameMatcher = attributes.name;
        return Array.from(root.querySelectorAll("*")).filter(function (element) {
          if (roleOf(element) !== role) return false;
          return nameMatcher ? nameMatcher(accessibleName(element)) : true;
        });
      }
      if (body.startsWith("text=")) {
        const matcher = parseMatcher(body.slice("text=".length));
        const scope = root.nodeType === 9 ? root.querySelectorAll("body *") : root.querySelectorAll("*");
        return Array.from(scope).filter(function (element) { return matchesText(element, matcher); });
      }
      if (body.startsWith("label=")) {
        const matcher = parseMatcher(body.slice("label=".length));
        const scope = root.querySelectorAll("input,textarea,select,button,meter,output,progress,[aria-label],[aria-labelledby]");
        return Array.from(scope).filter(function (element) {
          return labelsOf(element).some(function (label) { return matcher(label); });
        });
      }
      if (body.startsWith("attr=")) {
        const attributes = parseAttributes(body.slice("attr=".length));
        const names = Object.keys(attributes);
        if (names.length === 0) unsupported("internal:attr requires at least one attribute");
        return Array.from(root.querySelectorAll("*")).filter(function (element) {
          return names.every(function (name) { return attributes[name](element.getAttribute(name) || ""); });
        });
      }
      if (body.startsWith("testid=")) {
        const attributes = parseAttributes(body.slice("testid=".length));
        const names = Object.keys(attributes);
        return Array.from(root.querySelectorAll("*")).filter(function (element) {
          return names.every(function (name) { return attributes[name](element.getAttribute(name) || ""); });
        });
      }
      unsupported("unsupported internal Playwright selector: " + body);
    }
    if (step.startsWith("css=")) return Array.from(root.querySelectorAll(step.slice(4)));
    if (step.startsWith("id=")) {
      const element = root.querySelector("#" + CSS.escape(step.slice(3)));
      return element ? [element] : [];
    }
    if (step.startsWith("data-testid=")) {
      const element = root.querySelector('[data-testid="' + CSS.escape(step.slice(12)) + '"]');
      return element ? [element] : [];
    }
    if (step.startsWith("text=")) {
      const body = step.slice(5);
      const exact = body.length >= 2 && body.startsWith('"') && body.endsWith('"');
      const value = (exact ? body.slice(1, -1) : body).trim().toLowerCase();
      const scope = root.nodeType === 9 ? root.querySelectorAll("body *") : root.querySelectorAll("*");
      return Array.from(scope).filter(function (element) {
        const text = textOf(element).trim().toLowerCase();
        return exact ? text === value : text.includes(value);
      });
    }
    if (step.startsWith("role=")) {
      const spec = step.slice(5);
      const match = /^([A-Za-z-]+)(?:\[name="(.*)"\])?$/.exec(spec);
      if (!match) throw new Error("unsupported Playwright role selector: " + spec);
      const role = match[1].toLowerCase();
      const name = match[2] ? match[2].trim().toLowerCase() : undefined;
      return Array.from(root.querySelectorAll("[role],button,a,input,select,textarea")).filter(function (element) {
        const actual = (element.getAttribute("role") ||
          (element.tagName === "BUTTON" ? "button" :
           element.tagName === "A" ? "link" : "textbox")).toLowerCase();
        if (actual !== role) return false;
        if (!name) return true;
        return textOf(element).trim().toLowerCase() === name;
      });
    }
    if (step.startsWith("xpath=")) {
      const doc = root.nodeType === 9 ? root : root.ownerDocument;
      const result = doc.evaluate(step.slice(6), root, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
      const nodes = [];
      for (let index = 0; index < result.snapshotLength; index += 1) nodes.push(result.snapshotItem(index));
      return nodes.filter(function (node) { return node && node.nodeType === 1; });
    }
    return Array.from(root.querySelectorAll(step));
  }

  function queryUnder(roots, step) {
    const result = [];
    const seen = new Set();
    for (const root of roots) {
      for (const element of resolveStep(root, step)) {
        if (!seen.has(element)) {
          seen.add(element);
          result.push(element);
        }
      }
    }
    return result;
  }

  function applyStep(current, step) {
    if (step.startsWith("internal:control=")) {
      const value = step.slice("internal:control=".length).trim();
      if (value !== "enter-frame") unsupported("unsupported internal:control=" + value);
      return current.map(function (element) {
        if (!element || element.nodeType !== 1) unsupported("internal:control=enter-frame expects an iframe element");
        const tag = element.tagName;
        if (tag !== "IFRAME" && tag !== "FRAME") unsupported("internal:control=enter-frame expects an iframe element");
        const doc = element.contentDocument;
        if (!doc) unsupported("internal:control=enter-frame cannot access a cross-origin frame");
        return doc;
      });
    }
    if (step.startsWith("internal:and=") || step.startsWith("internal:or=") ||
        step.startsWith("internal:has=") || step.startsWith("internal:has-not=")) {
      const separator = step.indexOf("=");
      const operation = step.slice("internal:".length, separator);
      let inner;
      try {
        inner = JSON.parse(step.slice(separator + 1));
      } catch (error) {
        unsupported("internal:" + operation + " requires a JSON-quoted selector");
      }
      if (typeof inner !== "string" || !inner) {
        unsupported("internal:" + operation + " requires a non-empty selector");
      }
      const anchor = current.find(function (element) { return element && element.nodeType === 1; });
      const doc = anchor ? anchor.ownerDocument : document;
      if (operation === "and") {
        const matches = new Set(resolveSelector(doc, inner));
        return current.filter(function (element) { return matches.has(element); });
      }
      if (operation === "or") {
        const result = current.slice();
        const seen = new Set(result);
        for (const element of resolveSelector(doc, inner)) {
          if (!seen.has(element)) {
            seen.add(element);
            result.push(element);
          }
        }
        return result;
      }
      if (operation === "has") {
        return current.filter(function (element) {
          return element && element.nodeType === 1 && resolveSelector(element, inner).length > 0;
        });
      }
      return current.filter(function (element) {
        return element && element.nodeType === 1 && resolveSelector(element, inner).length === 0;
      });
    }
    if (step.startsWith("internal:has-text=") || step.startsWith("internal:has-not-text=")) {
      const negate = step.startsWith("internal:has-not-text=");
      const matcher = parseMatcher(step.slice(step.indexOf("=") + 1));
      return current.filter(function (element) {
        const matched = Boolean(element && element.nodeType === 1 && matcher(textOf(element)));
        return negate ? !matched : matched;
      });
    }
    const nth = /^nth=(-?\d+)$/.exec(step);
    if (nth) {
      const requested = Number(nth[1]);
      const index = requested < 0 ? current.length + requested : requested;
      return index >= 0 && index < current.length ? [current[index]] : [];
    }
    return queryUnder(current, step);
  }

  function sortDocumentOrder(elements) {
    return elements.slice().sort(function (left, right) {
      if (left === right || !left || !right) return 0;
      if (left.ownerDocument !== right.ownerDocument) return 0;
      const relation = left.compareDocumentPosition(right);
      if (relation & 4) return -1;
      if (relation & 2) return 1;
      return 0;
    });
  }

  function resolveSelector(root, selectorText) {
    const steps = selectorText.split(">>").map(function (part) { return part.trim(); }).filter(Boolean);
    let current = [root];
    for (const step of steps) {
      current = applyStep(current, step);
      if (current.length === 0) break;
    }
    return sortDocumentOrder(current).filter(function (node) { return node && node.nodeType === 1; });
  }

  return resolveSelector(document, selector);
})()"###,
    );
    script
}

fn with_elements(selector: &str, body: &str) -> String {
    format!(
        r##"(() => {{
  const elements = {resolver};
  const visible = (element) => {{
    const style = getComputedStyle(element);
    const rect = element.getBoundingClientRect();
    return style.display !== "none" && style.visibility !== "hidden" &&
      Number(style.opacity) !== 0 && rect.width > 0 && rect.height > 0;
  }};
  const enabled = (element) => !element.disabled && element.getAttribute("aria-disabled") !== "true";
  {body}
}})()"##,
        resolver = selector_resolver(selector)
    )
}

fn probe_script(selector: &str) -> String {
    with_elements(
        selector,
        r#"if (!elements[0]) return { count: 0, visible: false, enabled: false, checked: false, x: 0, y: 0 };
  const element = elements[0];
  element.scrollIntoView({ block: "center", inline: "center" });
  const rect = element.getBoundingClientRect();
  return {
    count: elements.length,
    visible: visible(element),
    enabled: enabled(element),
    checked: element.checked === true,
    x: rect.left + rect.width / 2,
    y: rect.top + rect.height / 2,
  };"#,
    )
}

async fn evaluate(
    port: &ShellBrowserPort,
    key: Option<String>,
    script: &str,
) -> Result<Value, (String, String)> {
    port.eval(key, script)
        .await
        .map_err(|(_, message)| ("execution_error".to_string(), message))
}

async fn wait_probe(
    port: &ShellBrowserPort,
    key: Option<String>,
    selector: &str,
    timeout: Duration,
    require_visible: bool,
    require_enabled: bool,
) -> Result<Value, (String, String)> {
    let deadline = Instant::now() + timeout;
    loop {
        let probe = evaluate(port, key.clone(), &probe_script(selector)).await?;
        let count = probe.get("count").and_then(Value::as_u64).unwrap_or(0);
        let visible = probe
            .get("visible")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let enabled = probe
            .get("enabled")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        if count > 0 && (!require_visible || visible) && (!require_enabled || enabled) {
            return Ok(probe);
        }
        if Instant::now() >= deadline {
            return Err(timeout_error(format!(
                "Timeout waiting for locator '{selector}'{}",
                if require_visible {
                    " to be visible"
                } else {
                    ""
                }
            )));
        }
        tokio::time::sleep(POLL_INTERVAL).await;
    }
}

fn modifier_mask(value: Option<&Value>) -> u32 {
    let Some(modifiers) = value.and_then(Value::as_array) else {
        return 0;
    };
    let mut mask = 0;
    for modifier in modifiers.iter().filter_map(Value::as_str) {
        mask |= match modifier {
            "Alt" => 1,
            "Control" | "ControlOrMeta" => 2,
            "Meta" => 4,
            "Shift" => 8,
            _ => 0,
        };
    }
    mask
}

fn press_parts(value: &str) -> Result<(String, u32), (String, String)> {
    let mut parts: Vec<&str> = value
        .split('+')
        .map(str::trim)
        .filter(|part| !part.is_empty())
        .collect();
    let Some(key) = parts.pop() else {
        return Err(invalid("locator.press requires a key"));
    };
    let mut mask = 0;
    for modifier in parts {
        mask |= match modifier {
            "Alt" => 1,
            "Control" | "ControlOrMeta" => 2,
            "Meta" => 4,
            "Shift" => 8,
            _ => return Err(invalid(format!("unsupported press modifier: {modifier}"))),
        };
    }
    Ok((key.to_string(), mask))
}

async fn click_at(
    port: &ShellBrowserPort,
    key: Option<String>,
    x: f64,
    y: f64,
    button: &str,
    double_click: bool,
    modifiers: u32,
) -> Result<(), (String, String)> {
    port.cdp(
        key.clone(),
        "Input.dispatchMouseEvent",
        json!({ "type": "mouseMoved", "x": x, "y": y }),
    )
    .await?;
    let click_count = if double_click { 2 } else { 1 };
    for event_type in ["mousePressed", "mouseReleased"] {
        port.cdp(
            key.clone(),
            "Input.dispatchMouseEvent",
            json!({
                "type": event_type,
                "x": x,
                "y": y,
                "button": button,
                "clickCount": click_count,
                "modifiers": modifiers,
            }),
        )
        .await?;
    }
    Ok(())
}

async fn fill_locator(
    port: &ShellBrowserPort,
    key: Option<String>,
    selector: &str,
    value: &str,
    replace: bool,
) -> Result<(), (String, String)> {
    let script = with_elements(
        selector,
        &format!(
            r#"const element = elements[0];
  if (!element) throw new Error("locator not found");
  element.focus();
  const next = {value};
  const resolved = {replace} ? next : String(element.value ?? "") + next;
  if (element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement) {{
    const proto = element instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
    const setter = Object.getOwnPropertyDescriptor(proto, "value")?.set;
    if (setter) setter.call(element, resolved); else element.value = resolved;
    element.dispatchEvent(new Event("input", {{ bubbles: true }}));
    element.dispatchEvent(new Event("change", {{ bubbles: true }}));
  }} else if (element.isContentEditable) {{
    element.textContent = resolved;
    element.dispatchEvent(new InputEvent("input", {{ bubbles: true, inputType: "insertText", data: resolved }}));
  }} else {{
    element.value = resolved;
    element.dispatchEvent(new Event("input", {{ bubbles: true }}));
  }}
  return true;"#,
            value = serde_json::to_string(value).unwrap_or_else(|_| "\"\"".to_string()),
            replace = if replace { "true" } else { "false" },
        ),
    );
    let result = evaluate(port, key, &script).await?;
    if result != Value::Bool(true) {
        return Err((
            "execution_error".to_string(),
            "locator.fill failed".to_string(),
        ));
    }
    Ok(())
}

async fn locator_action(
    port: &ShellBrowserPort,
    key: Option<String>,
    action: &Value,
    timeout: Duration,
) -> Result<Value, (String, String)> {
    let Some(selector) = action.get("selector").and_then(Value::as_str) else {
        return Err(invalid("locator action requires `selector`"));
    };
    let Some(operation) = action.get("operation").and_then(Value::as_str) else {
        return Err(invalid("locator action requires `operation`"));
    };
    match operation {
        "count" => evaluate(
            port,
            key,
            &with_elements(selector, "return elements.length;"),
        )
        .await,
        "allTextContents" => evaluate(
            port,
            key,
            &with_elements(
                selector,
                "return elements.map((element) => element.textContent ?? \"\");",
            ),
        )
        .await,
        "isVisible" => evaluate(
            port,
            key,
            &with_elements(
                selector,
                "return Boolean(elements[0] && visible(elements[0]));",
            ),
        )
        .await,
        "isEnabled" => evaluate(
            port,
            key,
            &with_elements(
                selector,
                "return Boolean(elements[0] && enabled(elements[0]));",
            ),
        )
        .await,
        "textContent" => evaluate(
            port,
            key,
            &with_elements(
                selector,
                "if (!elements[0]) throw new Error(\"locator not found\"); return elements[0].textContent;",
            ),
        )
        .await,
        "innerText" => evaluate(
            port,
            key,
            &with_elements(
                selector,
                "if (!elements[0]) throw new Error(\"locator not found\"); return elements[0].innerText;",
            ),
        )
        .await,
        "getAttribute" => {
            let Some(attribute) = action.get("attribute").and_then(Value::as_str) else {
                return Err(invalid("locator.getAttribute requires `attribute`"));
            };
            evaluate(
                port,
                key,
                &with_elements(
                    selector,
                    &format!(
                        "if (!elements[0]) throw new Error(\"locator not found\"); return elements[0].getAttribute({});",
                        serde_json::to_string(attribute).unwrap_or_else(|_| "\"\"".to_string())
                    ),
                ),
            )
            .await
        }
        "evaluate" => {
            let Some(expression) = action.get("expression").and_then(Value::as_str) else {
                return Err(invalid("locator.evaluate requires `expression`"));
            };
            let arg = action.get("arg").cloned().unwrap_or(Value::Null);
            let kind = action
                .get("expressionKind")
                .and_then(Value::as_str)
                .unwrap_or("string");
            let body = if kind == "function" {
                format!(
                    "if (!elements[0]) throw new Error(\"locator not found\"); return ({expression})(elements[0], {arg});"
                )
            } else {
                format!(
                    "if (!elements[0]) throw new Error(\"locator not found\"); const arg = {arg}; return ({expression});"
                )
            };
            evaluate(port, key, &with_elements(selector, &body)).await
        }
        "waitFor" => {
            let state = action
                .get("state")
                .and_then(Value::as_str)
                .unwrap_or("visible");
            let deadline = Instant::now() + timeout;
            loop {
                let probe = evaluate(port, key.clone(), &probe_script(selector)).await?;
                let count = probe.get("count").and_then(Value::as_u64).unwrap_or(0);
                let visible = probe.get("visible").and_then(Value::as_bool).unwrap_or(false);
                let matched = match state {
                    "attached" => count > 0,
                    "detached" => count == 0,
                    "visible" => count > 0 && visible,
                    "hidden" => count == 0 || !visible,
                    _ => return Err(invalid(format!("unsupported waitFor state: {state}"))),
                };
                if matched {
                    return Ok(Value::Null);
                }
                if Instant::now() >= deadline {
                    return Err(timeout_error(format!(
                        "Timeout waiting for locator '{selector}' to be {state}"
                    )));
                }
                tokio::time::sleep(POLL_INTERVAL).await;
            }
        }
        "click" | "dblclick" => {
            let force = action.get("force").and_then(Value::as_bool).unwrap_or(false);
            let probe = wait_probe(port, key.clone(), selector, timeout, !force, !force).await?;
            let x = probe.get("x").and_then(Value::as_f64).unwrap_or(0.0);
            let y = probe.get("y").and_then(Value::as_f64).unwrap_or(0.0);
            let button = action
                .get("button")
                .and_then(Value::as_str)
                .unwrap_or("left");
            click_at(
                port,
                key,
                x,
                y,
                button,
                operation == "dblclick",
                modifier_mask(action.get("modifiers")),
            )
            .await?;
            Ok(Value::Null)
        }
        "fill" => {
            wait_probe(port, key.clone(), selector, timeout, true, true).await?;
            let value = action
                .get("value")
                .map(|value| match value {
                    Value::String(text) => text.clone(),
                    other => other.to_string(),
                })
                .unwrap_or_default();
            let replace = action
                .get("replace")
                .and_then(Value::as_bool)
                .unwrap_or(true);
            fill_locator(port, key, selector, &value, replace).await?;
            Ok(Value::Null)
        }
        "press" => {
            wait_probe(port, key.clone(), selector, timeout, true, true).await?;
            let Some(value) = action.get("value").and_then(Value::as_str) else {
                return Err(invalid("locator.press requires `value`"));
            };
            let (key_name, mut modifiers) = press_parts(value)?;
            modifiers |= modifier_mask(action.get("modifiers"));
            let Some((code, virtual_key, key_value)) = scripts::key_fields(&key_name) else {
                return Err(invalid(format!("unsupported key: {key_name}")));
            };
            evaluate(
                port,
                key.clone(),
                &with_elements(selector, "if (!elements[0]) throw new Error(\"locator not found\"); elements[0].focus(); return true;"),
            )
            .await?;
            for event_type in ["keyDown", "keyUp"] {
                port.cdp(
                    key.clone(),
                    "Input.dispatchKeyEvent",
                    json!({
                        "type": event_type,
                        "key": key_value,
                        "code": code,
                        "windowsVirtualKeyCode": virtual_key,
                        "nativeVirtualKeyCode": virtual_key,
                        "modifiers": modifiers,
                    }),
                )
                .await?;
            }
            Ok(Value::Null)
        }
        "setChecked" => {
            let Some(checked) = action.get("checked").and_then(Value::as_bool) else {
                return Err(invalid("locator.setChecked requires `checked`"));
            };
            let probe = wait_probe(port, key.clone(), selector, timeout, true, true).await?;
            let current = probe.get("checked").and_then(Value::as_bool).unwrap_or(false);
            if current != checked {
                let x = probe.get("x").and_then(Value::as_f64).unwrap_or(0.0);
                let y = probe.get("y").and_then(Value::as_f64).unwrap_or(0.0);
                click_at(port, key.clone(), x, y, "left", false, 0).await?;
                let after = wait_probe(port, key, selector, timeout, true, true).await?;
                if after.get("checked").and_then(Value::as_bool) != Some(checked) {
                    return Err((
                        "execution_error".to_string(),
                        format!("locator.setChecked({checked}) did not change the element state"),
                    ));
                }
            }
            Ok(Value::Null)
        }
        "selectOption" => {
            wait_probe(port, key.clone(), selector, timeout, true, true).await?;
            let selections = action
                .get("selections")
                .cloned()
                .unwrap_or_else(|| json!([]));
            evaluate(
                port,
                key,
                &with_elements(
                    selector,
                    &format!(
                        r#"const element = elements[0];
  if (!(element instanceof HTMLSelectElement)) throw new Error("locator.selectOption requires a select element");
  const selections = {selections};
  const values = [];
  for (const selection of selections) {{
    let option;
    if (selection.value !== undefined) option = Array.from(element.options).find((candidate) => candidate.value === selection.value);
    else if (selection.label !== undefined) option = Array.from(element.options).find((candidate) => candidate.label === selection.label || candidate.text === selection.label);
    else if (selection.index !== undefined) option = element.options[selection.index];
    if (!option) throw new Error("select option not found");
    option.selected = true;
    values.push(option.value);
  }}
  element.dispatchEvent(new Event("input", {{ bubbles: true }}));
  element.dispatchEvent(new Event("change", {{ bubbles: true }}));
  return values;"#,
                        selections = selections
                    ),
                ),
            )
            .await
        }
        "downloadMedia" => {
            wait_probe(port, key.clone(), selector, timeout, true, true).await?;
            evaluate(
                port,
                key,
                &with_elements(
                    selector,
                    r#"const element = elements[0];
  const media = element.closest?.("img, video, source, a[href]") ??
    element.querySelector?.("img, video, source, a[href]") ?? element;
  const read = (value, name) => typeof value?.[name] === "string" ? value[name] : null;
  const url = read(media, "currentSrc") ?? read(media, "src") ?? read(media, "href") ?? "";
  if (!url) throw new Error("Matched element does not expose a downloadable URL");
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = url.split("/").pop()?.split("?")[0] || "download";
  anchor.rel = "noopener";
  anchor.style.display = "none";
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  return true;"#,
                ),
            )
            .await
        }
        other => Err(invalid(format!("unsupported locator operation: {other}"))),
    }
}

async fn element_screenshot(
    port: &ShellBrowserPort,
    key: Option<String>,
    action: &Value,
) -> Result<Value, (String, String)> {
    let x = action.get("x").and_then(Value::as_f64).unwrap_or(0.0);
    let y = action.get("y").and_then(Value::as_f64).unwrap_or(0.0);
    let script = format!(
        r#"(() => {{
  const element = document.elementFromPoint({x}, {y});
  if (!element) return null;
  element.scrollIntoView({{ block: "center", inline: "center" }});
  const rect = element.getBoundingClientRect();
  return {{ x: rect.left, y: rect.top, width: rect.width, height: rect.height }};
}})()"#
    );
    let rect = evaluate(port, key.clone(), &script).await?;
    let x = rect.get("x").and_then(Value::as_f64).unwrap_or(0.0);
    let y = rect.get("y").and_then(Value::as_f64).unwrap_or(0.0);
    let width = rect.get("width").and_then(Value::as_f64).unwrap_or(0.0);
    let height = rect.get("height").and_then(Value::as_f64).unwrap_or(0.0);
    if width <= 0.0 || height <= 0.0 {
        return Err(invalid(
            "playwright.elementScreenshot found no visible element",
        ));
    }
    let raw = port
        .cdp(
            key,
            "Page.captureScreenshot",
            json!({
                "format": "png",
                "fromSurface": true,
                "clip": { "x": x, "y": y, "width": width, "height": height, "scale": 1 }
            }),
        )
        .await?;
    let data = raw.get("data").and_then(Value::as_str).ok_or_else(|| {
        (
            "execution_error".to_string(),
            "CDP captureScreenshot returned no data".to_string(),
        )
    })?;
    Ok(json!({
        "image": { "base64": data, "mimeType": "image/png" }
    }))
}

async fn wait_for_event(
    port: &ShellBrowserPort,
    key: Option<String>,
    action: &Value,
) -> Result<Value, (String, String)> {
    let Some(event) = action.get("event").and_then(Value::as_str) else {
        return Err(invalid("playwright.waitForEvent requires `event`"));
    };
    if event == "filechooser" {
        return Err(unsupported("File uploads are not supported by iab"));
    }
    if event != "download" {
        return Err(invalid(format!("unsupported waitForEvent event: {event}")));
    }
    #[cfg(not(windows))]
    {
        return Err(unsupported(
            "download events require the WebView2 child webview (Windows only)",
        ));
    }
    #[cfg(windows)]
    {
        let before: std::collections::HashSet<String> =
            port.download_ids(key.as_deref()).into_iter().collect();
        let deadline = Instant::now() + download_timeout_of(action);
        loop {
            for id in port.download_ids(key.as_deref()) {
                if !before.contains(&id) {
                    return Ok(json!({ "id": id }));
                }
            }
            if Instant::now() >= deadline {
                return Err(timeout_error("Timeout waiting for download"));
            }
            tokio::time::sleep(POLL_INTERVAL).await;
        }
    }
}

async fn download_path(
    port: &ShellBrowserPort,
    key: Option<String>,
    action: &Value,
) -> Result<Value, (String, String)> {
    let Some(download_id) = action.get("downloadId").and_then(Value::as_str) else {
        return Err(invalid("playwright.downloadPath requires `downloadId`"));
    };
    #[cfg(not(windows))]
    {
        let _ = download_id;
        return Err(unsupported(
            "download events require the WebView2 child webview (Windows only)",
        ));
    }
    #[cfg(windows)]
    {
        let Some(path) = port.download_path_for(download_id, key.as_deref()) else {
            return Err((
                "backend_unavailable".to_string(),
                "download is unavailable for this tab".to_string(),
            ));
        };
        let deadline = Instant::now() + download_timeout_of(action);
        loop {
            if path.is_file() {
                return Ok(Value::String(path.to_string_lossy().to_string()));
            }
            if Instant::now() >= deadline {
                return Err(timeout_error("Timeout waiting for download path"));
            }
            tokio::time::sleep(POLL_INTERVAL).await;
        }
    }
}

pub async fn execute(
    port: &ShellBrowserPort,
    key: Option<String>,
    action: &Value,
    _timeout: Duration,
) -> Result<Value, (String, String)> {
    let timeout = timeout_of(action);
    let Some(name) = action.get("name").and_then(Value::as_str) else {
        return Err(invalid("playwright action requires `name`"));
    };
    match name {
        "locator" => locator_action(port, key, action, timeout).await,
        "domSnapshot" => evaluate(port, key, "document.documentElement.outerHTML").await,
        "elementInfo" => {
            let x = action.get("x").and_then(Value::as_f64).unwrap_or(0.0);
            let y = action.get("y").and_then(Value::as_f64).unwrap_or(0.0);
            let result = port.element_info(key, &json!({ "x": x, "y": y })).await;
            let element = result.get("element").cloned().unwrap_or(Value::Null);
            Ok(if element.is_null() {
                Value::Array(Vec::new())
            } else {
                Value::Array(vec![element])
            })
        }
        "evaluate" => {
            let Some(expression) = action.get("expression").and_then(Value::as_str) else {
                return Err(invalid("playwright.evaluate requires `expression`"));
            };
            let arg = action.get("arg").cloned().unwrap_or(Value::Null);
            let kind = action
                .get("expressionKind")
                .and_then(Value::as_str)
                .unwrap_or("string");
            let script = if kind == "function" {
                format!("({expression})({arg})")
            } else {
                format!("(() => {{ const arg = {arg}; return ({expression}); }})()")
            };
            evaluate(port, key, &script).await
        }
        "waitForLoadState" => {
            let state = action
                .get("state")
                .and_then(Value::as_str)
                .unwrap_or("load");
            if state == "networkidle" {
                return Err(unsupported(
                    "playwright.waitForLoadState does not support networkidle",
                ));
            }
            let deadline = Instant::now() + timeout;
            loop {
                let ready = evaluate(port, key.clone(), "document.readyState").await?;
                let ready = ready.as_str().unwrap_or("loading");
                let matched = if state == "domcontentloaded" {
                    ready != "loading"
                } else {
                    ready == "complete"
                };
                if matched {
                    return Ok(Value::Null);
                }
                if Instant::now() >= deadline {
                    return Err(timeout_error(format!(
                        "Timeout waiting for load state {state}"
                    )));
                }
                tokio::time::sleep(POLL_INTERVAL).await;
            }
        }
        "waitForURL" => {
            let Some(pattern) = action.get("url").and_then(Value::as_str) else {
                return Err(invalid("playwright.waitForURL requires `url`"));
            };
            let deadline = Instant::now() + timeout;
            loop {
                let url = evaluate(port, key.clone(), "location.href").await?;
                let url = url.as_str().unwrap_or("");
                if url_matches(pattern, url) {
                    return Ok(Value::String(url.to_string()));
                }
                if Instant::now() >= deadline {
                    return Err(timeout_error(format!("Timeout waiting for URL {pattern}")));
                }
                tokio::time::sleep(POLL_INTERVAL).await;
            }
        }
        "elementScreenshot" => element_screenshot(port, key, action).await,
        "waitForEvent" => wait_for_event(port, key, action).await,
        "downloadPath" => download_path(port, key, action).await,
        "fileChooserSetFiles" => Err(unsupported("File uploads are not supported by iab")),
        other => Err(invalid(format!("unsupported playwright action: {other}"))),
    }
}

fn url_matches(pattern: &str, url: &str) -> bool {
    if !pattern.contains('*') {
        return url == pattern;
    }
    let parts: Vec<&str> = pattern.split('*').collect();
    let mut rest = url;
    if let Some(first) = parts.first() {
        if !first.is_empty() {
            if !rest.starts_with(first) {
                return false;
            }
            rest = &rest[first.len()..];
        }
    }
    for part in parts.iter().skip(1).take(parts.len().saturating_sub(2)) {
        if part.is_empty() {
            continue;
        }
        let Some(index) = rest.find(part) else {
            return false;
        };
        rest = &rest[index + part.len()..];
    }
    match parts.last() {
        Some(last) if !last.is_empty() => rest.ends_with(last),
        _ => true,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn selector_resolver_supports_css_xpath_chaining_and_internal_selectors() {
        let script = selector_resolver("#app");
        assert!(script.contains("#app"));
        assert!(script.contains("css="));
        assert!(script.contains("data-testid="));
        assert!(script.contains("xpath="));
        assert!(script.contains("nth="));
        assert!(script.contains("split(\">>\")"));
        for internal in [
            "internal:control=",
            "internal:and=",
            "internal:or=",
            "internal:has=",
            "internal:has-not=",
            "internal:has-text=",
            "internal:has-not-text=",
        ] {
            assert!(script.contains(internal), "resolver must handle {internal}");
        }
        for shorthand in ["role=", "text=", "label=", "attr=", "testid="] {
            assert!(
                script.contains(&format!("body.startsWith(\"{shorthand}\")")),
                "resolver must handle internal:{shorthand}"
            );
        }
        assert!(script.contains("unsupported internal Playwright selector"));
        assert!(script.contains("cannot access a cross-origin frame"));
    }

    #[test]
    fn selector_resolver_embeds_the_selector_as_json() {
        let selector = "internal:text=\"a \\\"quoted\\\" value\"i";
        let script = selector_resolver(selector);
        let encoded = serde_json::to_string(selector).unwrap();
        assert!(script.contains(&encoded));
        assert!(script.starts_with("(() => {\n  const selector = "));
    }

    #[test]
    fn probe_and_fill_scripts_embed_escaped_values() {
        let probe = probe_script("a[href=\"x\"]");
        assert!(probe.contains("a[href=\\\"x\\\"]"));
        assert!(probe.contains("scrollIntoView"));
        let fill = with_elements("input[name=\"q\"]", "return true;");
        assert!(fill.contains("input[name=\\\"q\\\"]"));
    }

    #[test]
    fn press_parts_split_modifiers_and_key() {
        assert_eq!(press_parts("Control+A").unwrap(), ("A".to_string(), 2));
        assert_eq!(
            press_parts("Shift+Meta+Enter").unwrap(),
            ("Enter".to_string(), 12)
        );
        assert_eq!(press_parts("Enter").unwrap(), ("Enter".to_string(), 0));
        assert!(press_parts("Bogus+Enter").is_err());
        assert!(press_parts("").is_err());
    }

    #[test]
    fn url_matching_supports_star_wildcards() {
        assert!(url_matches(
            "https://example.com/*",
            "https://example.com/a/b"
        ));
        assert!(url_matches(
            "https://example.com/a",
            "https://example.com/a"
        ));
        assert!(!url_matches(
            "https://example.com/a",
            "https://example.com/b"
        ));
        assert!(!url_matches("https://example.com/*", "https://other.com/a"));
    }

    #[test]
    fn timeout_is_clamped_to_the_playwright_default() {
        assert_eq!(timeout_of(&json!({})), DEFAULT_TIMEOUT);
        assert_eq!(
            timeout_of(&json!({ "timeoutMs": 1 })),
            Duration::from_millis(1)
        );
        assert_eq!(timeout_of(&json!({ "timeoutMs": 99_999 })), DEFAULT_TIMEOUT);
    }

    #[test]
    fn download_timeout_is_clamped_to_two_minutes() {
        assert_eq!(download_timeout_of(&json!({})), DEFAULT_TIMEOUT);
        assert_eq!(
            download_timeout_of(&json!({ "timeoutMs": 1 })),
            Duration::from_millis(1)
        );
        assert_eq!(
            download_timeout_of(&json!({ "timeoutMs": 999_999 })),
            Duration::from_secs(120)
        );
    }

    #[tokio::test]
    async fn wait_for_event_rejects_filechooser_and_unknown_events() {
        let port = ShellBrowserPort::new(crate::browser_view::BrowserViewRegistry::default());
        let filechooser = wait_for_event(
            &port,
            None,
            &json!({ "name": "waitForEvent", "event": "filechooser" }),
        )
        .await
        .unwrap_err();
        assert_eq!(filechooser.0, "capability_unsupported");
        assert!(filechooser.1.contains("File uploads"));

        let unknown = wait_for_event(
            &port,
            None,
            &json!({ "name": "waitForEvent", "event": "console" }),
        )
        .await
        .unwrap_err();
        assert_eq!(unknown.0, "invalid_input");

        let missing = wait_for_event(&port, None, &json!({ "name": "waitForEvent" }))
            .await
            .unwrap_err();
        assert_eq!(missing.0, "invalid_input");
    }

    #[tokio::test]
    async fn download_path_requires_a_known_download_id() {
        let port = ShellBrowserPort::new(crate::browser_view::BrowserViewRegistry::default());
        let missing_id = download_path(&port, None, &json!({ "name": "downloadPath" }))
            .await
            .unwrap_err();
        assert_eq!(missing_id.0, "invalid_input");

        let unknown = download_path(
            &port,
            None,
            &json!({ "name": "downloadPath", "downloadId": "missing" }),
        )
        .await
        .unwrap_err();
        assert_eq!(unknown.0, "backend_unavailable");
    }
}
